package com.clipsync.core
import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test
class ProtocolTest { @Test fun vectors(){assertEquals("hello",FrameCodec.decode(FrameCodec.encode(ClipMessage(MessageType.TEXT,text="hello"))).text)} @Test fun splitsMulti(){val r=FrameReader();val f=FrameCodec.encode(ClipMessage(MessageType.TEXT,text="hello"));assertTrue(r.push(f.copyOfRange(0,4)).isEmpty());assertEquals(1,r.push(f.copyOfRange(4,f.size)).size);val both=FrameCodec.encode(ClipMessage(MessageType.ACK))+FrameCodec.encode(ClipMessage(MessageType.PING));assertEquals(2,r.push(both).size)} @Test fun guards(){val a=ClipVersion(1,"a","a",ClipMessage(MessageType.IMAGE));val b=ClipVersion(2,"b","b",ClipMessage(MessageType.TEXT,text="x"));val p=PendingSlot();p.put(a);p.put(b);assertEquals(b,p.take());assertTrue(b>a)} @Test fun engineCases(){val e=SyncEngine();val img=ClipVersion(1,"a","img",ClipMessage(MessageType.IMAGE));val txt=ClipVersion(2,"a","txt",ClipMessage(MessageType.TEXT,text="new"));e.local(img);e.local(txt);assertEquals(txt,e.pending.take());e.connect();e.local(img);e.local(txt);assertEquals(txt,e.scheduler.next());assertTrue(e.apply(txt));assertTrue(!e.apply(txt));e.pause();assertEquals(EngineState.PAUSED,e.state);e.resume();assertEquals(EngineState.CONNECTED,e.state)} }
